public class C421 {
    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            String[] parts = br.readLine().split(" ");
            int a = Integer.parseInt(parts[0]);
            int b = Integer.parseInt(parts[1]);
            int l = Integer.parseInt(parts[2]) - 1;
            int r = Integer.parseInt(parts[3]) - 1;
            int len = a + b;
            int diff = r - l;
            int answer;
            if (diff >= 2 * len) {
                answer = Math.max(a + 1, 2 * a - b);
            } else {
                r -= len * (l / len);
                l %= len;
                answer = computeDifference(a, b, l, r);
            }
            System.out.println(answer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static int computeDifference(int a, int b, int l, int r) {
        int first = b < a ? b : a - 1;
        int last = a - 1;
        StringBuilder sb = new StringBuilder();
        char ch = 'a';
        for (int i = 0; i < a; i++) {
            sb.append(ch++);
        }
        ch = l < a ? sb.charAt(last) : sb.charAt(first);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        boolean[] used = new boolean[30];
        for (int i = 0; i < a; i++) {
            used[sb.charAt(sb.length() - i - 1) - 'a'] = true;
        }
        int ptr = 0;
        for (int i = 0; i < a; i++) {
            while (used[ptr]) ptr++;
            sb.append((char) ('a' + ptr));
            used[ptr] = true;
        }
        ch = sb.charAt(Math.min(b, a - 1) + a + b);
        for (int i = 0; i < b; i++) {
            sb.append(ch);
        }
        for (int i = 0; i < a + b; i++) {
            sb.append(sb.charAt(i));
        }
        return countUniqueLetters(sb.toString(), l, r);
    }

    static int countUniqueLetters(String s, int l, int r) {
        boolean[] used = new boolean[30];
        for (int i = l; i <= r; i++) {
            used[s.charAt(i) - 'a'] = true;
        }
        int count = 0;
        for (int i = 0; i < 30; i++) {
            if (used[i]) count++;
        }
        return count;
    }
}
