#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int computeDifference(int a, int b, int l, int r);
int countUniqueLetters(const std::string& s, int l, int r);

int main() {
    int a, b, l, r;
    std::cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;
    int len = a + b;
    int diff = r - l;
    int answer;
    if (diff >= 2 * len) {
        answer = std::max(a + 1, 2 * a - b);
    } else {
        r -= len * (l / len);
        l %= len;
        answer = computeDifference(a, b, l, r);
    }
    std::cout << answer << std::endl;
    return 0;
}

int computeDifference(int a, int b, int l, int r) {
    int first = b < a ? b : a - 1;
    int last = a - 1;
    std::string sb;
    for (int i = 0; i < a; i++) {
        sb += ('a' + i);
    }
    char ch;
    if (l < a) {
        ch = sb[last];
    } else {
        ch = sb[first];
    }
    for (int i = 0; i < b; i++) {
        sb += ch;
    }
    std::vector<bool> used(30, false);
    for (int i = 0; i < a; i++) {
        used[sb[sb.size() - i - 1] - 'a'] = true;
    }
    int ptr = 0;
    for (int i = 0; i < a; i++) {
        while (used[ptr]) ptr++;
        sb += ('a' + ptr);
        used[ptr] = true;
    }
    int index = std::min(b, a - 1) + a + b;
    ch = sb[index];
    for (int i = 0; i < b; i++) {
        sb += ch;
    }
    for (int i = 0; i < a + b; i++) {
        sb += sb[i];
    }
    return countUniqueLetters(sb, l, r);
}

int countUniqueLetters(const std::string& s, int l, int r) {
    std::vector<bool> used(30, false);
    for (int i = l; i <= r; i++) {
        used[s[i] - 'a'] = true;
    }
    int count = 0;
    for (int i = 0; i < 30; i++) {
        if (used[i]) count++;
    }
    return count;
}

